using FluentValidation;using FluentValidation.Results;using Microsoft.EntityFrameworkCore;using SchoolERP.Api.ErrorHandling;using SchoolERP.Application.Exceptions;using Xunit;namespace SchoolERP.UnitTests;public sealed class ApiExceptionMapperTests{private readonly ApiExceptionMapper _mapper=new();[Fact]public void Validation_is_grouped_camel_case_and_deduplicated(){var x=_mapper.Map(new ValidationException([new ValidationFailure("Name","Required"),new ValidationFailure("Name","Required"),new ValidationFailure("Email","Invalid")]));Assert.Equal((400,ErrorCodes.ValidationFailed),(x.StatusCode,x.Code));Assert.Equal(["Required"],x.Errors!["name"]);Assert.Equal(["Invalid"],x.Errors["email"]);}[Fact]public void Not_found_is_safe_and_specific(){var x=_mapper.Map(new ResourceNotFoundException("Campus"));Assert.Equal((404,"Campus.NotFound","Campus not found."),(x.StatusCode,x.Code,x.Message));}[Fact]public void Conflict_is_409(){var x=_mapper.Map(new HouseCodeConflictException());Assert.Equal((409,"House.CodeAlreadyExists"),(x.StatusCode,x.Code));}[Fact]public void Concurrency_is_409(){var x=_mapper.Map(new DbUpdateConcurrencyException("database detail"));Assert.Equal((409,ErrorCodes.Concurrency),(x.StatusCode,x.Code));Assert.DoesNotContain("database",x.Message,StringComparison.OrdinalIgnoreCase);}[Fact]public void Unknown_exception_does_not_expose_message(){var x=_mapper.Map(new Exception("sensitive internal detail at C:\\secret.cs"));Assert.Equal((500,ErrorCodes.Unexpected,"An unexpected error occurred."),(x.StatusCode,x.Code,x.Message));Assert.DoesNotContain("sensitive",x.Message);}}
